/* Southern Cross Telecom (Telecommunications) - source database seed for the pipeline Copy demo
   Plays the role of: Network Inventory Management System (on-prem Oracle)
   Run this whole script ONCE in a Fabric SQL database (or Azure SQL / SQL Server). Then release the days in order:
       EXEC src.usp_release_day 1;   -- before the first pipeline run
       EXEC src.usp_release_day 2;   -- before the second run
       EXEC src.usp_release_day 3;   -- before the third run (adds a new column = schema drift)
   Generated by tools/build_kit.py - all data is fictional. */
IF SCHEMA_ID('src') IS NULL EXEC('CREATE SCHEMA src');
GO
DROP TABLE IF EXISTS src.network_elements; DROP TABLE IF EXISTS src.fault_tickets; DROP TABLE IF EXISTS src.stage_network_elements; DROP TABLE IF EXISTS src.stage_fault_tickets;
CREATE TABLE src.network_elements (element_id INT NOT NULL, element_code NVARCHAR(30), element_name NVARCHAR(100), element_type NVARCHAR(30), region NVARCHAR(40), status NVARCHAR(30), criticality INT, capacity_users DECIMAL(12,1), install_date DATE, last_modified DATETIME2(0), CONSTRAINT pk_network_elements PRIMARY KEY (element_id));
CREATE TABLE src.fault_tickets (ticket_id INT NOT NULL, element_id INT, fault_category NVARCHAR(30), priority INT, status NVARCHAR(30), opened_ts DATETIME2(0), resolved_ts DATETIME2(0), field_cost_aud DECIMAL(12,2), engineer_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0), CONSTRAINT pk_fault_tickets PRIMARY KEY (ticket_id));
CREATE TABLE src.stage_network_elements (release_day INT NOT NULL, element_id INT, element_code NVARCHAR(30), element_name NVARCHAR(100), element_type NVARCHAR(30), region NVARCHAR(40), status NVARCHAR(30), criticality INT, capacity_users DECIMAL(12,1), install_date DATE, last_modified DATETIME2(0), firmware_channel NVARCHAR(50));
CREATE TABLE src.stage_fault_tickets (release_day INT NOT NULL, ticket_id INT, element_id INT, fault_category NVARCHAR(30), priority INT, status NVARCHAR(30), opened_ts DATETIME2(0), resolved_ts DATETIME2(0), field_cost_aud DECIMAL(12,2), engineer_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0));
GO
GO
CREATE OR ALTER PROCEDURE src.usp_release_day @day INT
AS
BEGIN
    SET NOCOUNT ON;
    IF @day >= 3 AND COL_LENGTH('src.network_elements', 'firmware_channel') IS NULL
        EXEC('ALTER TABLE src.network_elements ADD firmware_channel NVARCHAR(50) NULL');
    DELETE t FROM src.network_elements t WHERE EXISTS (SELECT 1 FROM src.stage_network_elements s WHERE s.release_day = @day AND s.element_id = t.element_id);
    IF @day >= 3
        EXEC('UPDATE t SET t.firmware_channel = s.firmware_channel FROM src.network_elements t JOIN src.stage_network_elements s ON s.element_id = t.element_id AND s.release_day = 3');
    DELETE t FROM src.fault_tickets t WHERE EXISTS (SELECT 1 FROM src.stage_fault_tickets s WHERE s.release_day = @day AND s.ticket_id = t.ticket_id);
    SELECT @day AS released_day, (SELECT COUNT(*) FROM src.network_elements) AS network_elements, (SELECT COUNT(*) FROM src.fault_tickets) AS fault_tickets;
END;
GO
