    INSERT INTO src.network_elements (element_id, element_code, element_name, element_type, region, status, criticality, capacity_users, install_date, last_modified) SELECT element_id, element_code, element_name, element_type, region, status, criticality, capacity_users, install_date, last_modified FROM src.stage_network_elements WHERE release_day = @day;
